using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Eye of Vecna (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class EyeOfVecna2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("eye-of-vecna", null, 0, MagicItemType.WondrousItem, ItemRarity.Artifact, true, ContentSource.RealmForge,
			Charges(8, ItemRecharge.LongRest, "1d4+4"),
			("Occhio di Vecna", "Oggetto meraviglioso, artefatto (richiede sintonia)",
			"Vecna fu uno dei maghi più potenti di tutti i tempi e forgiò un terribile impero. Temendo la morte, imparò da Orcus, principe demoniaco della non morte, il rituale per diventare un lich, e divenne il più grande di tutti. Il suo luogotenente Kas, forse sedotto dalla spada che lo stesso Vecna gli aveva donato, pose fine al suo regno in una battaglia che ridusse la sua torre in cenere. Di Vecna rimasero solo una mano e un occhio, che cercano ancora di compiere la volontà del Sussurrato.\n\nL'occhio sembra un organo iniettato di sangue strappato dall'orbita. Per entrare in sintonia con esso, il personaggio deve cavarsi un occhio e premere l'artefatto nell'orbita vuota: l'occhio vi si innesta, diventa un occhio dorato con la pupilla a fessura come quella di un gatto e resta lì fino alla morte del personaggio. Se viene rimosso, il personaggio muore.\n\n***Proprietà casuali.*** 1 proprietà benefica minore, 1 proprietà benefica maggiore e 1 proprietà dannosa minore.\n\n***Proprietà dell'occhio.*** L'allineamento del personaggio diventa neutrale malvagio e ottiene i seguenti benefici:\n\n- Ha vista pura.\n- Può usare un'azione per vedere come se indossasse un *anello della vista a raggi X*, e terminare l'effetto con un'azione bonus.\n- L'occhio ha 8 cariche. Con un'azione, il personaggio può consumarne una o più per lanciare uno degli incantesimi seguenti (CD 18): *chiaroveggenza* (2 cariche), *corona di follia* (1 carica), *disintegrazione* (4 cariche), *dominare mostri* (5 cariche) o *sguardo penetrante* (4 cariche). All'alba di ogni giorno l'occhio recupera 1d4 + 4 cariche consumate. Ogni volta che il personaggio lancia un incantesimo con l'occhio, c'è una probabilità del 5 percento che Vecna gli strappi l'anima, la divori e prenda il controllo del suo corpo come un burattino: il personaggio diventa un PNG controllato dal GM.\n\n***Occhio e Mano insieme.*** Se il personaggio è in sintonia anche con la *Mano di Vecna*, ottiene i benefici aggiuntivi descritti per la Mano.\n\n***Distruggere l'occhio.*** Se l'Occhio e la Mano di Vecna sono innestati sulla stessa creatura e questa viene uccisa dalla *Spada di Kas*, entrambi prendono fuoco, si riducono in cenere e sono distrutti per sempre. Qualsiasi altro tentativo sembra riuscire, ma l'artefatto ricompare in uno dei tanti covi segreti di Vecna, in attesa di essere ritrovato.", null),
			("Eye of Vecna", "Wondrous item, artifact (requires attunement)",
			"Vecna was one of the mightiest wizards of all time and forged a terrible empire. Fearing death, he learned from Orcus, the demon prince of undeath, the ritual to become a lich, and he became the greatest of them all. His lieutenant Kas, perhaps seduced by the sword Vecna himself had given him, ended his reign in a battle that left his tower in ashes. All that remained of Vecna were a hand and an eye, which still seek to carry out the Whispered One's will.\n\nThe eye looks like a bloodshot organ torn from its socket. To attune to it, you must gouge out one of your eyes and press the artifact into the empty socket: it grafts itself there, turns into a golden eye with a slit pupil like a cat's, and stays until you die. If it is ever removed, you die.\n\n***Random Properties.*** 1 minor beneficial property, 1 major beneficial property and 1 minor detrimental property.\n\n***Properties of the Eye.*** Your alignment becomes neutral evil and you gain the following benefits:\n\n- You have truesight.\n- You can use an action to see as if you were wearing a *ring of X-ray vision*, and end the effect as a bonus action.\n- The eye has 8 charges. As an action, you can expend one or more of them to cast one of these spells (DC 18): *clairvoyance* (2 charges), *crown of madness* (1 charge), *disintegrate* (4 charges), *dominate monster* (5 charges) or *eyebite* (4 charges). The eye regains 1d4 + 4 expended charges daily at dawn. Each time you cast a spell from it, there is a 5 percent chance that Vecna tears out your soul, devours it and takes over your body like a puppet: you become an NPC under the DM's control.\n\n***Eye and Hand Together.*** If you are also attuned to the *Hand of Vecna*, you gain the extra benefits described for the Hand.\n\n***Destroying the Eye.*** If the Eye and Hand of Vecna are grafted onto the same creature and that creature is slain by the *Sword of Kas*, both burst into flame, turn to ash and are destroyed forever. Any other attempt seems to work, but the artifact reappears in one of Vecna's many hidden vaults, waiting to be found again.", null));
	}
}
